INSERT INTO sections (section, title, notes) VALUES
  ('I', 'Live Animals; Animal Products', '[{"number": "1", "text": "Any reference in this Section to a particular genus or species of an animal, except where the context otherwise requires, includes a reference to the young of that genus or species."}, {"number": "2", "text": "Except where the context otherwise requires, throughout this Schedule, any reference to \"dried\" products also covers products which have been dehydrated, evaporated or freeze-dried."}]'::jsonb),
  ('II', 'Vegetable Products', '[{"number": "1", "text": "In this Section, the term \"pellets\" means products which have been agglomerated either directly by compression or by the addition of a binder in a proportion not exceeding 3 (percent) by weight."}]'::jsonb),
  ('III', 'Animal or Vegetable Fats and Oils', '[]'::jsonb),
  ('IV', 'Prepared Foodstuffs; Beverages, Spirits, Vinegar; Tobacco', '[{"number": "1", "text": "In this Section, the term \"pellets\" means products which have been agglomerated either directly by compression or by the addition of a binder in a proportion not exceeding 3 (percent) by weight."}]'::jsonb),
  ('V', 'Mineral Products', '[]'::jsonb),
  ('VI', 'Products of the Chemical or Allied Industries', '[{"number": "1", "text": "(A) Goods (other than radioactive ores) answering to a description in heading 2844 or 2845 are to be classified in those headings and in no other heading of this Schedule. (B) Subject to paragraph (A) above, goods answering to a description in heading 2843, 2846 or 2852 are to be classified in those headings and in no other heading of this Section."}, {"number": "2", "text": "Subject to Note 1 above, goods classifiable in heading 3004, 3005, 3006, 3212, 3303, 3304, 3305, 3306, 3307, 3506, 3707 or 3808 by reason of being put up in measured doses or for retail sale are to be classified in those headings and in no other heading of this Schedule."}, {"number": "3", "text": "Goods put up in sets consisting of two or more separate constituents,some or all of which fall in this Section and are intended to be mixed together to obtain a product of Section VI or VII, are to be classified in the heading appropriate to that product, provided that the constituents are: (a) having regard to the manner in which they are put up, clearly identifiable as being intended to be used together without first being repacked; (b) presented together; and (c) identifiable, whether by their nature or by the relative proportions in which they are present, as being complementary one to another."}, {"number": "4", "text": "Where a product answers to a description in one or more of the headings in Section VI by virtue of being described by name or function and also to heading 3827, then it is classifiable in a heading that references the product by name or function and not under heading 3827."}]'::jsonb),
  ('VII', 'Plastics and Articles thereof; Rubber and Articles thereof', '[{"number": "1", "text": "Goods put up in sets consisting of two or more separate constituents,some or all of which fall in this Section and are intended to be mixed together to obtain a product of Section VI or VII, are to be classified in the heading appropriate to that product, provided that the constituents are : (a) having regard to the manner in which they are put up, clearly identifiable as being intended to be used together without first being repacked; (b) presented together; and (c) identifiable, whether by their nature or by the relative proportionsin which they are present, as being complementary one to another."}, {"number": "2", "text": "Except for the goods of heading 3918 or 3919, plastics, rubber, and articles thereof, printed with motifs, characters or pictorial representations, which are not merely subsidiary to the primary use of the goods, fall in Chapter 49."}]'::jsonb),
  ('VIII', 'Raw Hides and Skins, Leather, Furskins and Articles thereof', '[]'::jsonb),
  ('IX', 'Wood and Articles of Wood; Cork; Manufactures of Straw', '[]'::jsonb),
  ('X', 'Pulp of Wood; Paper and Paperboard', '[]'::jsonb),
  ('XI', 'Textiles and Textile Articles', '[{"number": "1", "text": "This section does not cover: a. animal brush-making bristles or hair (heading 0502); horsehair or horsehair waste (heading 0511); b. human hair or articles of human hair (heading 0501, 6703 or 6704), except filtering or straining cloth of a kind commonly used in oil-presses or the like (heading 5911); c. cotton linters or other vegetable materials of Chapter 14; d. asbestos of heading 2524 or articles of asbestos or other products of heading 6812 or 6813; e. articles of heading 3005 or 3006; yarn used to clean between the teeth (dental floss), in individual retail packages, of heading 3306; f. sensitised textiles of heading 3701 to 3704; g. monofilament of which any cross-sectional dimension exceeds 1 mm or strip or the like (for example, artificial straw) of an apparent width exceeding 5 mm, of plastics (Chapter 39), or plaits or fabrics or other basketware or wickerwork of such monofilament or strip (Chapter 46); h. woven, knitted or crocheted fabrics, felt or nonwovens, impregnated, coated, covered or laminated with plastics, or articles thereof, of Chapter 39; ij. woven, knitted or crocheted fabrics, felt or nonwovens, impregnated, coated, covered or laminated with rubber, or articles thereof, of Chapter 40; k. hides or skins with their hair or wool on (Chapter 41 or 43) or articles of furskin, artificial fur or articles thereof, of heading 4303 or 4304; l. articles of textile materials of heading 4201 or 4202; m. products or articles of Chapter 48 (for example, cellulose wadding); n. footwear or parts of footwear, gaiters or leggings or similar articles of Chapter 64; o. hairnets or other headgear or parts thereof of Chapter 65; p. goods of Chapter 67; q. abrasive-coated textile material (heading 6805) and also carbon fibres or articles of carbon fibres of heading 6815; r. glass fibres or articles of glass fibres, other than embroidery with glass thread on a visible ground of fabric (Chapter 70); s. articles of Chapter 94 (for example, furniture, bedding, luminaires and lighting fittings); t. articles of Chapter 95 (for example, toys, games, sports requisites and nets); u. articles of Chapter 96 (for example, brushes, travel sets for sewing, slide fasteners, typewriter ribbons, sanitary towels (pads) and tampons, napkins (diapers) and napkin liners); or v. articles of Chapter 97."}, {"number": "2", "text": "(A) Goods classifiable in Chapters 50 to 55 or in heading 5809 or 5902 and of a mixture of two or more textile materials are to be classified as if consisting wholly of that one textile material which predominates by weight over any other single textile material. When no one textile material predominates by weight, the goods are to be classified as if consisting wholly of that one textile material which is covered by the heading which occurs last in numerical order among those which equally merit consideration. (B) For the purposes of the above rule: a. gimped horsehair yarn (heading 5110) and metallised yarn (heading 5605) are to be treated as a single textile material the weight of which is to be taken as the aggregate of the weights of its components; for the classification of woven fabrics, metal thread is to be regarded as a textile material; b. the choice of the appropriate heading shall be effected by determining first the Chapter and then the applicable heading within that Chapter, disregarding any materials not classified in that Chapter; c. when both Chapters 54 and 55 are involved with any other chapter, Chapters 54 and 55 are to be treated as a single chapter; d. where a Chapter or a heading refers to goods of different textile materials, such materials are to be treated as a single textile material. (C) The provisions of paragraphs (A) and (B) above apply also to the yarns referred to in note 3, 4, 5 or 6 below."}, {"number": "3", "text": "(A) For the purposes of this section, and subject to the exceptions in paragraph (B) below, yarns (single, multiple (folded) or cabled) of the following descriptions are to be treated as ''twine, cordage, ropes and cables'': a. of silk or waste silk, measuring more than 20.000 decitex; b. of man-made fibres (including yarn of two or more monofilaments of Chapter 54), measuring more than 10.000 decitex; c. of true hemp or flax: (1) polished or glazed, measuring 1.429 decitex or more; or (2) not polished or glazed, measuring more than 20.000 decitex; d. of coir, consisting of three or more plies; e. of other vegetable fibres, measuring more than 20.000 decitex; or f. reinforced with metal thread. (B) Exceptions: a. yarn of wool or other animal hair and paper yarn, other than yarn reinforced with metal thread; b. man-made filament tow of Chapter 55 and multifilament yarn without twist or with a twist of less than five turns per metre of Chapter 54; c. silk worm gut of heading 5006, and monofilaments of Chapter 54; d. metallised yarn of heading 5605; yarn reinforced with metal thread is subject to paragraph (A) (f) above; and e. chenille yarn, gimped yarn and loop wale-yarn of heading 5606."}, {"number": "4", "text": "(A) For the purposes of Chapters 50, 51, 52, 54 and 55, the expression ''put up for retail sale'' in relation to yarn means, subject to the exceptions in paragraph (B) below, yarn (single, multiple (folded) or cabled) put up: a. on cards, reels, tubes or similar supports, of a weight (including support) not exceeding: (1) 85 g in the case of silk, waste silk or man-made filament yarn; or (2) 125 g in other cases; b. in balls, hanks or skeins of a weight not exceeding: (1) 85 g in the case of man-made filament yarn of less than 3.000 decitex, silk or silk waste; (2) 125 g in the case of all other yarns of less than 2.000 decitex; or (3) 500 g in other cases; c. in hanks or skeins comprising several smaller hanks or skeins separated by dividing threads which render them independent one of the other, each of uniform weight not exceeding: (1) 85 g in the case of silk, waste silk or man-made filament yarn; or (2) 125 g in other cases. (B) Exceptions: a. single yarn of any textile material, except: (1) single yarn of wool or fine animal hair, unbleached; and (2) single yarn of wool or fine animal hair, bleached, dyed or printed, measuring more than 5.000 decitex; b. multiple (folded) or cabled yarn, unbleached: (1) of silk or waste silk, however put up; or (2) of other textile material except wool or fine animal hair, in hanks or skeins; c. multiple (folded) or cabled yarn of silk or waste silk, bleached, dyed or printed, measuring 133 decitex or less; and d. single, multiple (folded) or cabled yarn of any textile material: (1) in cross-reeled hanks or skeins; or (2) put up on supports or in some other manner indicating its use in the textile industry (for example, on cops, twisting mill tubes, pirns, conical bobbins or spindles, or reeled in the form of cocoons for embroidery looms)."}, {"number": "5", "text": "For the purposes of heading 5204, 5401 and 5508, the expression ''sewing thread'' means multiple (folded) or cabled yarn: a. put up on supports (for example, reels, tubes) of a weight (including support) not exceeding 1,000 grams; b. dressed for use as sewing thread; and c. with a final ''Z'' twist."}, {"number": "6", "text": "For the purposes of this section, the expression ''high-tenacity yarn'' means yarn having a tenacity, expressed in cN/tex (centinewtons per tex), greater than the following: single yarn of nylon or other polyamides, or of polyesters: 60 cN/tex, multiple (folded) or cabled yarn of nylon or other polyamides, or of polyesters: 53 cN/tex, single, multiple (folded) or cabled yarn of viscose rayon: 27 cN/tex."}, {"number": "7", "text": "For the purposes of this section, the expression ''made up'' means: a. cut otherwise than into squares or rectangles; b. produced in the finished state, ready for use (or merely needing separation by cutting dividing threads) without sewing or other working (for example, certain dusters, towels, tablecloths, scarf squares, blankets); c. cut to size and with at least one heat-sealed edge with a visibly tapered or compressed border and the other edges treated as described in any other sub-paragraph of this note, but excluding fabrics, the cut edges of which, have been prevented from unravelling by hot cutting or by other simple means; d. hemmed or with rolled edges, or with a knotted fringe at any of the edges, but excluding fabrics, the cut edges of which have been prevented from unravelling by whipping or by other simple means; e. cut to size and having undergone a process of drawn thread work; f. assembled by sewing, gumming or otherwise (other than piece goods consisting of two or more lengths of identical material joined end to end and piece goods composed of two or more textiles assembled in layers, whether or not padded); g. knitted or crocheted to shape, whether presented as separate items or in the form of a number of items in the length."}, {"number": "8", "text": "For the purposes of Chapters 50 to 60: a. Chapters 50 to 55 and 60 and, except where the context otherwise requires, Chapters 56 to 59 do not apply to goods made up within the meaning of note 7 above; and b. Chapters 50 to 55 and 60 do not apply to goods of Chapters 56 to 59."}, {"number": "9", "text": "The woven fabrics of Chapters 50 to 55 include fabrics consisting of layers of parallel textile yarns superimposed on each other at acute or right angles. These layers are bonded at the intersections of the yarns by an adhesive or by thermal bonding."}, {"number": "10", "text": "Elastic products consisting of textile materials combined with rubber threads are classified in this section."}, {"number": "11", "text": "For the purposes of this section, the expression ''impregnated'' includes ''dipped''."}, {"number": "12", "text": "For the purposes of this section, the expression ''polyamides'' includes ''aramids''."}, {"number": "13", "text": "For the purposes of this section and, where applicable, throughout the nomenclature, the expression ''elastomeric yarn'' means filament yarn, including monofilament, of synthetic textile material, other than textured yarn, which does not break on being extended to three times its original length and which returns, after being extended to twice its original length, within a period of five minutes, to a length not greater than one and a half times its original length."}, {"number": "14", "text": "Unless the context otherwise requires, textile garments of different headings are to be classified in their own headings, even if put up in sets for retail sale. For the purposes of this note, the expression ''textile garments'' means garments of heading 6101 to 6114 and heading 6201 to 6211."}, {"number": "15", "text": "Subject to Note 1 to Section XI, textiles, garments and other textile articles, incorporating chemical, mechanical or electronic components for additional functionality, whether incorporated as built-in components or within the fibre or fabric, are classified in their respective headings in Section XI provided that they retain the essential character of the goods of this Section."}]'::jsonb),
  ('XII', 'Footwear, Headgear, Umbrellas; Artificial Flowers', '[]'::jsonb),
  ('XIII', 'Articles of Stone, Plaster, Cement, Ceramics, Glass', '[]'::jsonb),
  ('XIV', 'Natural or Cultured Pearls, Precious Stones, Precious Metals', '[]'::jsonb),
  ('XV', 'Base Metals and Articles of Base Metal', '[{"number": "1", "text": "This Section does not cover : (a) prepared paints, inks or other products with a basis of metallic flakes or powder (headings 3207 to 3210, 3212, 3213 or 3215); (b) ferro-cerium or other pyrophoric alloys(heading 3606); (c) headgear or parts thereof of heading 6506 or 6507; (d) umbrella frames or other articles of heading 6603; (e) goods of Chapter 71 (for example, precious metal alloys, base metal clad with precious metal, imitation jewellery); (f) articles of Section XVI (machinery, mechanical a pliances and electrical goods); (g) assembled railway or tramway track (heading 8608) or other articles of Section XVII (vehicles, ships and boats, aircraft); (h) instruments or apparatus of Section XVIII, including clock or watch springs; (ij) lead shot prepared for ammunition (heading 9306) or other articles of Section XIX (arms and ammunition); (k) articles of Chapter 94 (for example, furniture, mattress supports, luminaires and lighting fittings, illuminated signs, prefabricated buildings); (l) articles of Chapter 95 (for example, toys, games, sports requisites); (m) hand sieves, buttons, pens, pencil-holders, pen nibs, monopods, bipods, tripods and similar articles or other articles of Chapter 96 (miscellaneous manufactured articles); or\"\"\"\" (n) articles of Chapter 97 (for example, works of art)."}, {"number": "2", "text": "Throughout this Schedule, the expression \"\"\"\"parts of general use\"\"\"\" means : (a) articles of heading 7307, 7312, 7315, 7317 or 7318 and similar articles of other base metal, other than articles specially designed for use exclusively in implants in medical, surgical, dental or veterinary sciences (heading 9021); (b) springs and leaves for springs, of base metal, other than clock or watch springs (heading 9114); and (c) articles of headings 8301, 8302, 8308, 8310 and frames and mirrors, of base metal, of heading 8306. In Chapters 73 to 76 and 78 to 82 (but not in heading 7315) references to parts of goods do not include references to parts of general use as defined above. Subject to the preceding paragraph and to Note 1 to Chapter 83, the articles of Chapter 82 or 83 are excluded from Chapters 72 to 76 and 78 to 81."}, {"number": "3", "text": "Throughout this Schedule, the expression \"\"base metals\"\" means : iron and steel, copper, nickel, aluminium, lead, zinc, tin, tungsten (wolfram), molybdenum, tantalum, magnesium, cobalt, bismuth, cadmium, titanium, zirconium, antimony, manganese, beryllium, chromium, germanium, vanadium, gallium, hafnium, indium, niobium (columbium),rhenium and thallium."}, {"number": "4", "text": "Throughout this Schedule, the term \"cermets\" means products containing a microscopic heterogenous combination of a metallic component and a ceramic component. The term \"cermets\" includes sintered metal carbides (metal carbides sintered with a metal)."}, {"number": "5", "text": "Classification of alloys (other than ferro-alloys and master alloys as defined in Chapters 72 and 74) : (a) an alloy of base metals is to be classified as an alloy of the metal which predominates by weight over each of the other metals; (b) an alloy composed of base metals of this Section and of elements not falling within this Section is to be treated as an alloy of base metals of this Section if the total weight of such metals equals or exceeds the total weight of the other elements present; (c) in this Section, the term \"\"\"\"alloys\"\"\"\" includes sintered mixtures of metal powders, heterogeneous intimate mixtures obtained by melting (other than cermets) and intermetallic compounds."}, {"number": "6", "text": "Unlessthe context otherwise requires, any reference in this Schedule to a base metal includes a reference to alloys which, by virtue of Note 5 above, are to be classified as alloys of that metal."}, {"number": "7", "text": "Classification of composite articles: Except where the headings otherwise require, articles of base metal (including articles of mixed materials treated as articles of base metal under the General Interpretive Rules) containing two or more base metals areto be treated as articles of the base metal predominating by weight over each of the other metals. For this purpose: (a) iron and steel, or different kinds of iron or steel, are regarded as one and the same metal; (b) an alloy isregarded as being entirely composed of that metal as an alloy of which, by virtue of Note 5, it is classified; and (c) a cermet of heading 8113 is regarded as a single base metal."}, {"number": "8", "text": "In this Section, the following expressions have the meanings hereby assigned to them : (a) waste and scrap: (i) all metal waste and scrap; (ii) metal goods definitely not usable as such because of breakage, cutting-up, wear or other reasons. (b) Powders: products of which 90% or more by weight passes through a sieve having a mesh aperture of 1 mm."}, {"number": "9", "text": "For the purposes of Chapters 74 to 76 and 78 to 81, the following expressions shall have the meanings hereby assigned to them: (a) Bars and rods: Rolled, extruded, drawn or forged products, not in coils, which have a uniform solid cross-section along their whole length in the shape of circles, ovals, rectangles (including squares), equilateral triangles or regular convex polygons (including \"\"\"\"flattened circles\"\"\"\" and \"\"\"\"modified rectangles\"\"\"\", of which two opposite sides are convex arcs, the other two sides being straight, of equal length and parallel). Products with a rectangular (including square), triangular or polygonal cross-section may have corners rounded along their whole length. The thickness of such products which have a rectangular (including \"\"\"\"modified rectangular\"\"\"\") cross-section exceeds one-tenth of the width. The expression also covers cast or sintered products, of the same forms and dimensions, which have been subsequently worked after production (otherwise than by simple trimming or descaling), provided that they have not thereby assumed the character of articles or products of other headings. Wirebars and billets of Chapter 74 with their ends tapered or otherwise worked simply to facilitate their entry into machines for converting them into, for example, drawing stock (wire-rod) or tubes, are however to be taken to be unwrought copper of heading 7403. This provision applies mutatis mutandis to the products of Chapter 81. (b) Profiles: Rolled, extruded, drawn, forged or formed products, coiled or not, of a uniform cross-section along their whole length, which do not conform to any of the definitions of bars, rods, wire, plates, sheets, strip, foil, tubes or pipes. The expression also covers cast or sintered products, of the same forms, which have been subsequently worked after production (otherwise than by simple trimming or de-scaling), provided that they have not thereby assumed the character of articles or products of other headings. (c) Wire: Rolled, extruded or drawn products, in coils, which have a uniform solid cross-section along their whole length in the shape of circles, ovals, rectangles (including squares), equilateral triangles or regular convex polygons (including \"\"\"\"flattened circles\"\"\"\" and \"\"\"\"modified rectangles\"\"\"\", of which two opposite sides are convex arcs, the other two sides being straight, of equal length and parallel). Products with a rectangular (including square), triangular or polygonal cross-section may have corners rounded along their whole length. The thickness of such products which have a rectangular (including \"\"\"\"modified rectangular\"\"\"\") cross-section exceeds one-tenth of the width. (d) Plates, sheets, strip and foil: Flat-surfaced products (other than the unwrought products of heading 8001), coiled or not, of solid rectangular (other than square) cross-section with or without rounded corners (including \"\"\"\"modified rectangles\"\"\"\" of which two opposite sides are convex arcs, the other two sides being straight, of equal length and parallel) of a uniform thickness, which are: - of rectangular (including square) shape with a thickness not exceeding one-tenth of the width; - of a shape other than rectangular or square, of any size, provided that they do not assume the character of articles or products of other headings. Headings for plates, sheets, strip, and foil apply, inter alia, to plates, sheets, strip, and foil with patterns (for example, grooves, ribs, chequers, tears, buttons, lozenges) and to such products which have been perforated, corrugated, polished or coated, provided that they do not thereby assume the character of articles or products of other headings. (e) Tubes and pipes: Hollow products, coiled or not, which have a uniform cross-section with only one enclosed void along their whole length in the shape of circles, ovals, rectangles (including squares), equilateral triangles or regular convex polygons, and which have a uniform wall thickness. Products with a rectangular (including square), equilateral triangular or regular convex polygonal cross-section, which may have corners rounded along their whole length, are also to be considered as tubes and pipes provided the inner and outer crosssections are concentric and have the same form and orientation. Tubes and pipes of the foregoing cross-sections may be polished, coated, bent, threaded, drilled, waisted, expanded, cone-shaped or fitted with flanges, collars or rings."}]'::jsonb),
  ('XVI', 'Machinery and Mechanical Appliances; Electrical Equipment', '[{"number": "1", "text": "This Section does not cover : (a) transmission or conveyor belts or belting, of plastics of Chapter 39, or of vulcanised rubber (heading 4010), or other articles of a kind used in machinery or mechanical or electrical appliances or for other technical uses, of vulcanised rubber other than hard rubber (heading 4016); (b) articles of leather or of composition leather (heading 4205) or of furskin (heading 4303), of a kind used in machinery or mechanical appliances or for other technical uses; (c) bobbins, spools, cops, cones, cores, reels or similar supports, of any material (for example, Chapter 39, 40, 44 or 48 or Section XV); (d) perforated cards for Jacquard or similar machines (for example, Chapter 39 or 48 or Section XV); (e) transmission or conveyor belts or belting of textile material ( heading 5910) or other articles of textile material for technical uses(heading 5911); (f) precious or semi-precious stones (natural, synthetic or reconstructed) of headings 7102 to 7104, or articleswhollyofsuch stones of heading 7116 except unmountedworked sapphires and diamonds forstyli (heading 8522); (g) parts of general use, as defined in Note 2 to Section XV, of base metal (Section XV), or similar goods of plastics (Chapter 39); (h) drill pipe (heading 7304); (ij) endless belts of metal wire or strip (Section XV); (k) articles of Chapter 82 or 83; (l) articles of Section XVII; (m) articles of Chapter 90; (n) clocks, watches or other articles of Chapter 91; (o) interchangeable tools of heading 8207 or brushes of a kind used as parts of machines (heading 9603); similar interchangeable tools are to be classified according to the constituent material of their working part (for example, in Chapter 40, 42, 43, 45 or 59 or heading 6804 or 6909); (p) articles of Chapter 95; or (q) typewriter or similar ribbons, whether or not onspools or in cartridges (classified according to their constituent material, or in heading 9612 if inked or otherwise prepared for giving impressions), or monopods, bipods, tripods and similar articles, of heading 9620."}, {"number": "2", "text": "Subject to Note 1 to this Section, Note 1 to Chapter 84 and to Note 1 to Chapter 85, parts of machines (not being parts of the articles of heading 8484, 8544, 8545, 8546 or 8547) are to be classified according to the followingrules: (a) parts which are goodsincluded in any of the headings of Chapter 84 or 85 (other than headings 8409, 8431, 8448, 8466, 8473, 8487, 8503, 8522, 8529, 8538 and 8548) are in all casesto be classified in their respective headings; (b) other parts, if suitable for use solely or principally with a particular kind of machine, or with a number of machines of the same heading (including a machine of heading 8479 or 8543) are to be classified with the machines of that kind or in heading 8409, 8431, 8448, 8466, 8473, 8503, 8522, 8529 or 8538 as appropriate. However, parts which are equally suitable for use principally with the goods of headings 8517 and 8525 to 8528 are to be classified in heading 8517, and parts which are suitable for use solely or principally with the goods of heading 8524 are to be classified in heading 8529; (c) all other parts are to be classified in heading 8409, 8431, 8448, 8466, 8473, 8503, 8522, 8529 or 8538 as appropriate or, failing that, in heading 8487 or 8548."}, {"number": "3", "text": "Unless the context otherwise requires, composite machines consisting of two or more machines fitted together to form a whole and other machines designed for the purpose of performing two or more complementary or alternative functions are to be classified asif consisting only of that component or as being that machine which performs the principal function."}, {"number": "4", "text": "Where a machine (including a combination of machines) consists of individual components(whether separate or interconnected by piping, by transmission devices, by electric cables or by other devices) intended to contribute together to a clearly defined function covered by one of the headings in Chapter 84 or Chapter 85, then the whole fallsto be classified in the heading appropriate to that function."}, {"number": "5", "text": "For the purposes of these Notes, the expression \"machine\" means any machine, machinery, plant, equipment, apparatus or appliance cited in the headings of Chapter 84 or 85."}, {"number": "6", "text": "(a) Throughout the Nomenclature, the expression \"\"\"\"electrical and electronic waste and scrap\"\"\"\" means electrical and electronic assemblies, printed circuit boards and electrical or electronic articles that? (i) have been rendered unusable for their original purposes by breakage, cutting-up or other processes or are economically unsuitable for repair, refurbishment or renovation to render them fit for their original purposes; and (ii) are packaged or shipped in a manner not intended to protect individual articles from damage during transportation, loading and unloading operations; (b) mixed consignments of \"\"\"\"electrical and electronic waste and scrap\"\"\"\" and other waste and scrap are to be classified in heading 8549; (c) this Section does not cover municipal waste as defined in Note 4 to Chapter 38."}]'::jsonb),
  ('XVII', 'Vehicles, Aircraft, Vessels and Associated Transport Equipment', '[{"number": "1", "text": "This Section does not cover articles of heading 9503 or 9508 or bobsleighs, toboggans and the like of heading 9506."}, {"number": "2", "text": "The expressions \"parts\" and \"parts and accessories\" do not apply to the following articles, whether or not they are identifiable as for the goods of this Section: (a) joints, washers or the like of any material (classified according to their constituent material or in heading 8484) or other articles of vulcanised rubber other than hard rubber (heading 4016), (b) parts of general use, as defined in Note 2 to Section XV, of base metal (Section XV), or similar goods of plastics (Chapter 39), (c) articles of Chapter 82 (tools), (d) articles of heading 8306, (e) machines and apparatus of headings 8401 to 8479, or parts thereof, other than the radiators for the articles of this Section, articles of heading 8481 or 8482 or, provided they constitute integral parts of engines and motors, articles of heading 8483, (f) electrical machinery or equipment (Chapter 85), (g) articles of Chapter 90, (h) articles of Chapter 91, (ij) arms (Chapter 93), (k) luminaries and lighting fittings and parts thereof of heading 9405, or (l) brushes of a kind used as parts of vehicles (heading 9603)."}, {"number": "3", "text": "References in Chapters 86 to 88 to \"parts\" or \" accessories\" do not apply to parts or accessories which are not suitable for use solely or principally with the articles of those Chapters. A part or accessory which answers to a description in two or more of the headings of those Chapters is to be classified under that heading which corresponds to the principal use of that part of accessory."}, {"number": "4", "text": "For the purposes of this Section: (a) vehicles specially constructed to travel on both road and rail are classified under the appropriate heading of Chapter 87, (b) amphibious motor vehicles are classified under the appropriate heading of Chapter 87, (c) aircraft specially constructed so that they can also be used as road vehicles are classified under the appropriate heading of Chapter 88."}, {"number": "5", "text": "Air-cushion vehicles are to be classified within this Section with the vehicles to which they are most akin as follows: (a) in Chapter 86 if designed to travel on a guide-track (hovertrains), (b) in Chapter 87 if designed to travel over land or over both land and water, (c) in Chapter 89 if designed to travel over water, whether or not able to land on beaches or landing - stages or also able to travel over ice. Parts and accessories of air-cushion vehicles are to be classified in the same way as those of vehicles of the heading in which the air-cushion vehicles are classified under the above provisions. Hovertrain track fixtures and fittings are to be classified as railway track fixtures and fittings, and signalling, safety or traffic control equipment for hovertrain transport systems as signalling, safety or traffic control equipment for railways."}]'::jsonb),
  ('XVIII', 'Optical, Photographic, Cinematographic, Measuring Instruments; Clocks; Musical Instruments', '[]'::jsonb),
  ('XIX', 'Arms and Ammunition; Parts and Accessories thereof', '[]'::jsonb),
  ('XX', 'Miscellaneous Manufactured Articles', '[]'::jsonb),
  ('XXI', 'Works of Art, Collectors'' Pieces and Antiques', '[]'::jsonb);
